# Colorado Revised Statutes from the Office of Legislative Legal Services' own download (content.leg.colorado.gov
# "Download C.R.S. Titles": olls.info/crs/crs<year>-htm.zip, every title as Word-exported HTML). The official online
# C.R.S. is hosted by LexisNexis and is not read. Titles 1-44 (the Constitution file and the index are left out); a section
# is its bold number paragraph, its heading, its own paragraphs and its "Source:" line; editor's notes, cross references
# and annotations after it are not the law's words and are left out. A section printed twice (the version in force and the
# one "effective January 1, 2027") lands as the version in force. A repealed range ("1-1-401 to 1-1-403. (Repealed)") is
# cited "C.R.S. §§ 1-1-401 to 1-1-403".
import io, re, time, zipfile
from html.parser import HTMLParser

BASE = "https://olls.info/crs"
NUM = re.compile(r"(\d+(?:\.\d+)?-\d+(?:\.\d+)?-\d+(?:\.\d+)?)(?:\s+(?:to|and)\s+(\d+(?:\.\d+)?-\d+(?:\.\d+)?-\d+(?:\.\d+)?))?\.?(?=\s|$)")


class _Paras(HTMLParser):
    """Every <p> of a title as (text, bold text, centered): a section opens with a bold number, a part or article
    heading is centered, an editor's note opens with a bold label ending in ':'."""
    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.out, self.cur, self.b, self.skip = [], None, 0, 0

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self.skip += 1
        elif tag == "p":
            a = dict(attrs)
            self.cur = [[], [], "center" in ((a.get("align") or "") + (a.get("style") or "")).lower()]
        elif tag == "b":
            self.b += 1
        elif tag == "br" and self.cur:
            self.cur[0].append(chr(10))

    def handle_endtag(self, tag):
        if tag in ("script", "style") and self.skip:
            self.skip -= 1
        elif tag == "b" and self.b:
            self.b -= 1
            if self.cur:
                self.cur[1].append(" | ")
        elif tag == "p" and self.cur:
            text = "\n".join(" ".join(l.split()) for l in "".join(self.cur[0]).split("\n")).strip()
            if text:
                self.out.append((text, " ".join("".join(self.cur[1]).split()), self.cur[2]))
            self.cur = None

    def handle_data(self, d):
        if self.cur is not None and not self.skip:
            d = " ".join(d.split(chr(10)))        # Word wraps its source lines; only <br> breaks a line
            self.cur[0].append(d)
            if self.b:
                self.cur[1].append(d)


def _zip():
    y = int(time.strftime("%Y"))
    for year in (y + 1, y, y - 1):
        try:
            kind, raw = fetch(f"{BASE}/crs{year}-htm.zip")
        except Exception as e:  # noqa: BLE001 — next year's edition is not out yet
            log(f"crs{year}-htm.zip: {str(e)[:80]}")
            continue
        if kind == "zip":
            return year, zipfile.ZipFile(io.BytesIO(raw))
    raise IOError("no C.R.S. htm zip found at olls.info")


def sections():
    year, z = _zip()
    names = sorted(n for n in z.namelist() if re.search(r"title-(\d+(?:\.\d+)?)\.htm$", n) and not n.endswith("title-00.htm"))
    log(f"C.R.S. {year}: {len(names)} titles")
    for name in names:
        url = f"{BASE}/{name.rsplit('/', 1)[-1]}"
        p = _Paras()
        p.feed(z.read(name).decode("cp1252", "replace"))
        p.close()
        cur, got = None, {}

        def keep(it):
            old = got.get((it["id"], it["vars"]["to"]))
            future = re.match(r"\[Editor's note: This version of this section is effective (?!until)", it["text"])
            if old is None or (not future and re.match(r"\[Editor's note: This version of this section is effective (?!until)", old["text"])):
                got[(it["id"], it["vars"]["to"])] = it

        for text, bold, center in p.out + [("", "", True)]:
            m = NUM.match(text) if bold and NUM.match(bold) else None
            if m or center:
                if cur:
                    keep(cur["item"])
                cur = None
            if m:
                sid = m.group(1)
                rng = {"s": "§§", "to": f" to {m.group(2)}"} if m.group(2) else {"s": "§", "to": ""}
                rest = text[m.end():].strip()
                segs = [s.strip() for s in bold.split("|") if s.strip()]
                head = segs[1] if len(segs) > 1 and not NUM.fullmatch(segs[1].rstrip(".")) else ""
                if segs and NUM.match(segs[0]) and segs[0].rstrip(".") != m.group(0).rstrip("."):
                    head = segs[0][len(m.group(0)):].strip() or head        # number and heading in one bold run
                if m.group(2):
                    head = ""                                                   # a range has no heading of its own
                body = rest[len(head):].strip() if head and rest.startswith(head) else rest
                if re.search(r"\(Repealed\)\.?$", head):           # the repeal is the section's words, not its name
                    head = re.sub(r"\s*\(Repealed\)\.?$", "", head)
                    body = ("(Repealed)\n" + body).strip()
                cur = {"item": {"id": sid, "heading": head.rstrip(".").strip(), "text": body, "url": f"{url}#{m.group(1)}", "vars": rng},
                       "done": False}
                continue
            if not cur or cur["done"]:
                continue
            label = bold.split("|")[0].strip()
            if label and text.startswith(label) and label.endswith(":"):      # "Source: L. 92:", "Editor's note:", "Cross references:"
                if label.startswith("Source"):
                    cur["item"]["text"] = (cur["item"]["text"] + "\n" + text).strip()
                cur["done"] = True
                continue
            if text.upper() == "ANNOTATION":
                cur["done"] = True
                continue
            cur["item"]["text"] = (cur["item"]["text"] + "\n" + text).strip()
        log(f"{name}: {len(got)} sections")
        yield from got.values()
